Подпись создаётся свойством контроллера и добавляется при загрузке view; повторное появление не добавляет новую подпись.

import UIKit
final class ReadingController: UIViewController {
    var loadChapter: () -> String = { "Глава 1" }
    let titleLabel = UILabel()
    override func viewDidLoad() {
        super.viewDidLoad()
        view.addSubview(titleLabel)
    }
    override func viewWillAppear(_ animated: Bool) {
        super.viewWillAppear(animated)
        titleLabel.text = loadChapter()
    }
}
@MainActor
func checkAppearances() {
    let controller = ReadingController()
    controller.loadViewIfNeeded()
    controller.viewWillAppear(false)
    assert(controller.titleLabel.text == "Глава 1")
    controller.loadChapter = { "Глава 2" }
    controller.viewWillAppear(false)
    assert(controller.titleLabel.text == "Глава 2")
    assert(controller.titleLabel.superview === controller.view)
}

Ручной контекст проверяет ответ на два явных вызова, не запускает настоящий переход. Название обновилось, экземпляр подписи остался тем же.

