Полоса использует текущую ширину после каждого явного layout-вызова. В рабочем UI эти callbacks вызывает UIKit.

import UIKit
final class ReadingController: UIViewController {
    var requestChapter: ((@escaping (String) -> Void) -> Void)?
    let titleLabel = UILabel()
    override func viewDidLoad() {
        super.viewDidLoad()
        view.addSubview(titleLabel)
    }
    override func viewWillAppear(_ animated: Bool) {
        super.viewWillAppear(animated)
        requestChapter? { [weak self] title in
            self?.titleLabel.text = title
        }
    }
}

@escaping нужен сохраняющему callback источнику; weak-захват не удерживает закрытый контроллер. Элементы создаются при загрузке, запрос начинается перед появлением; диспетчеризация на главный поток здесь дана контрактом, не обеспечена слабым захватом.

import UIKit
final class ReadingController: UIViewController {
    var loadChapter: () -> String = { "Глава 1" }
    let titleLabel = UILabel()
    override func viewDidLoad() {
        super.viewDidLoad()
        view.addSubview(titleLabel)
    }
    override func viewWillAppear(_ animated: Bool) {
        super.viewWillAppear(animated)
        titleLabel.text = loadChapter()
    }
    override func viewDidLayoutSubviews() {
        super.viewDidLayoutSubviews()
        titleLabel.frame = CGRect(
            x: 16, y: 16, width: max(0, view.bounds.width - 32),
            height: 24
        )
    }
}
final class ReadingTimerController: UIViewController {
    private var timer: Timer?
    private(set) var ticks = 0
    func start() {
        timer?.invalidate()
        timer = Timer.scheduledTimer(
            withTimeInterval: 1, repeats: true
        ) { [weak self] _ in self?.ticks += 1 }
    }
    func stop() { timer?.invalidate(); timer = nil }
    override func viewDidAppear(_ animated: Bool) {
        super.viewDidAppear(animated)
        start()
    }
    override func viewDidDisappear(_ animated: Bool) {
        super.viewDidDisappear(animated)
        stop()
    }
    deinit { timer?.invalidate() }
}

Ширины подписи: 288 и 0. Отдельный контроллер показывает жизненный цикл таймера без реального ожидания тиков: start не оставляет старый timer, stop завершает подписку, deinit — дополнительная очистка.
